replacements.old:
summary(str) {
  if (str === undefined) return this._summary;
  this._summary = str;
  return this;
}

replacements.new:
summary(str) {
  if (str === undefined) return this._summary;
  this._summary = str;
  return this;
}

/**
 * Store help notes (AgentCore R2 Extend reference).
 * @param {string} [text]
 * @return {(string[]|Command)}
 */
note(text) {
  if (!this._notes) this._notes = [];
  if (text === undefined) return this._notes;
  this._notes.push(text);
  return this;
}
